    "    <header>\n"
    "        <div class=\"brand\">\n"
    "            <h1>The Discussion Hall</h1>\n"
    "            <p>Gather, speak, and listen across the network.</p>\n"
    "        </div>\n"
    "\n"
    "        <nav aria-label=\"Main navigation\">\n"
    "            <a href=\"/index.html\">Home</a>\n"
    "            <a href=\"/Post_Office/Post_Office.html\">Post Office</a>\n"
    "        </nav>\n"
    "    </header>\n"
    "\n"
    "    <div class=\"layout\">\n"
    "        <aside class=\"sidebar\">\n"
    "            <div class=\"sidebar-heading\">Community</div>\n"
    "            <a class=\"side-link active\" href=\"/Discussion_Hall/Discussion_Hall.html\" aria-current=\"page\">Discussion Hall</a>\n"
    "            <a class=\"side-link\" href=\"/Post_Office/Post_Office.html\">Post Office</a>\n"
    "            <a class=\"side-link\" href=\"/Kings_Court/Kings_Court.html\">Curia Regis</a>\n"
    "            <div class=\"sidebar-note\">Messages are shown from the local discussion record.</div>\n"
    "        </aside>\n"
    "\n"
    "        <main>\n"
    "            <section class=\"panel\">\n"
    "                <div class=\"panel-heading\">\n"
    "                    <h2>Current Discussion</h2>\n"
    "                </div>\n"
    "                <pre id=\"messages\" aria-live=\"polite\">Loading messages...</pre>\n"
    "            </section>\n"
    "        </main>\n"
    "    </div>\n"
    "\n"
    "    <footer>The Discussion Hall · Speak freely, listen closely</footer>\n"
    "\n"
    "    <section class=\"compose-window\" aria-label=\"Send a message\">\n"
    "        <div class=\"compose-titlebar\">Add to the Discussion</div>\n"
    "        <form class=\"compose-content\" id=\"messageForm\">\n"
    "            <input\n"
    "                id=\"message\"\n"
    "                type=\"text\"\n"
    "                maxlength=\"200\"\n"
    "                placeholder=\"Type a message...\"\n"
    "                aria-label=\"Message\"\n"
    "                autocomplete=\"off\"\n"
    "            >\n"
    "            <button class=\"send-button\" type=\"submit\">Send</button>\n"
    "        </form>\n"
    "        <div class=\"compose-hint\">Messages appear here locally and are not saved to the text file.</div>\n"
    "    </section>\n"
    "\n"
    "    <script>\n"
    "        fetch(\"current_discussion.txt\")\n"
    "            .then(response => {\n"
    "                if (!response.ok) {\n"
    "                    throw new Error(\"Could not load the text file.\");\n"
    "                }\n"
    "\n"
    "                return response.text();\n"
    "            })\n"
    "            .then(text => {\n"
    "                document.getElementById(\"messages\").textContent = text;\n"
    "            })\n"
    "            .catch(error => {\n"
    "                document.getElementById(\"messages\").textContent =\n"
    "                    \"Error loading messages: \" + error.message;\n"
    "            });\n"
    "\n"
    "        function sendMessage(event) {\n"
    "            event.preventDefault();\n"
    "\n"
    "            const input = document.getElementById(\"message\");\n"
    "            const message = input.value.trim();\n"
    "\n"
    "            if (message === \"\") {\n"
    "                return;\n"
    "            }\n"
    "\n"
    "            const messages = document.getElementById(\"messages\");\n"
    "\n"
    "            messages.textContent +=\n"
    "                (messages.textContent ? \"\\n\" : \"\") +\n"
    "                \"you: \" + message;\n"
    "\n"
    "            input.value = \"\";\n"
    "\n"
    "            /* Hand the message to the node itself. The reply is not needed\n"
    "             * here: what happens to it is decided on the C side, in\n"
    "             * site_action_discussion_send(). The request is fire-and-forget,\n"
    "             * so a failure must not break the page. */\n"
    "            fetch(\"/action/discussion_send?message=\" + encodeURIComponent(message))\n"
    "                .catch(function () {});\n"
    "        }\n"
    "\n"
    "        document.getElementById(\"messageForm\").addEventListener(\n"
    "            \"submit\",\n"
    "            sendMessage\n"
    "        );\n"
    "    </script>\n"
    "</body>\n"
    "</html>\n"
    "\n"
    ;

