    "\n"
    "<body>\n"
    "\n"
    "<header>\n"
    "    <div class=\"brand\">\n"
    "        <h1>The Post Office</h1>\n"
    "        <p>Messages travel far, even in the darkest times.</p>\n"
    "    </div>\n"
    "\n"
    "    <nav>\n"
    "        <button onclick=\"showFolder('inbox')\">Home</button>\n"
    "        <button onclick=\"loadMessages()\">Refresh</button>\n"
    "        <button onclick=\"openCompose()\">Compose</button>\n"
    "    </nav>\n"
    "</header>\n"
    "\n"
    "<div class=\"layout\">\n"
    "\n"
    "    <aside class=\"sidebar\">\n"
    "        <button class=\"compose-shortcut\" onclick=\"openCompose()\">\n"
    "            Compose Letter\n"
    "        </button>\n"
    "\n"
    "        <div class=\"sidebar-heading\">Mailbox</div>\n"
    "\n"
    "        <div class=\"folder active\" id=\"inboxFolder\"\n"
    "             onclick=\"showFolder('inbox')\">\n"
    "            Inbox\n"
    "        </div>\n"
    "\n"
    "        <div class=\"folder\" id=\"allFolder\"\n"
    "             onclick=\"showFolder('all')\">\n"
    "            All Messages\n"
    "        </div>\n"
    "\n"
    "        <div class=\"sidebar-note\">\n"
    "            Better to send a message than to keep it in your heart.\n"
    "        </div>\n"
    "    </aside>\n"
    "\n"
    "    <main class=\"main\">\n"
    "\n"
    "        <section class=\"panel\">\n"
    "            <div class=\"panel-heading\">\n"
    "                <h2 id=\"listTitle\">Inbox</h2>\n"
    "                <span class=\"message-count\" id=\"messageCount\">\n"
    "                    Loading...\n"
    "                </span>\n"
    "            </div>\n"
    "\n"
    "            <div id=\"emailList\">\n"
    "                <div class=\"empty-inbox\">Loading messages...</div>\n"
    "            </div>\n"
    "        </section>\n"
    "\n"
    "        <section class=\"panel\" id=\"messageViewer\">\n"
    "            <div class=\"viewer-placeholder\">\n"
    "                Select a sender to read their letter.\n"
    "            </div>\n"
    "        </section>\n"
    "\n"
    "    </main>\n"
    "\n"
    "</div>\n"
    "\n"
    "<footer>\n"
    "    The Post Office · Established in an age long forgotten\n"
    "</footer>\n"
    "\n"
    "<!-- COMPOSE WINDOW -->\n"
    "\n"
    "<div class=\"compose-window\" id=\"composeWindow\">\n"
    "\n"
    "    <div class=\"compose-titlebar\">\n"
    "        <span>New Letter</span>\n"
    "        <button type=\"button\" title=\"Minimize\"\n"
    "                onclick=\"toggleCompose()\">−</button>\n"
    "    </div>\n"
    "\n"
    "    <div class=\"compose-content\" id=\"composeContent\">\n"
    "        <form id=\"composeForm\">\n"
    "\n"
    "            <label for=\"recipient\">To whom it may concern:</label>\n"
    "            <input id=\"recipient\" type=\"text\" maxlength=\"100\"\n"
    "                   placeholder=\"Recipient's username\"\n"
    "                   autocomplete=\"off\">\n"
    "\n"
    "            <label for=\"composeMessage\">Your letter:</label>\n"
    "            <textarea id=\"composeMessage\" maxlength=\"5000\"\n"
    "                      placeholder=\"Write your message...\"></textarea>\n"
    "\n"
    "            <div class=\"compose-actions\">\n"
    "                <button class=\"send-button\" type=\"submit\">Send</button>\n"
    "                <span class=\"compose-hint\">Not yet dispatched</span>\n"
    "            </div>\n"
    "\n"
    "        </form>\n"
    "    </div>\n"
    "\n"
    "</div>\n"
    "\n"
    "<script>\n"
    "let messages = [];\n"
    "let selectedMessage = null;\n"
    "let currentFolder = \"inbox\";\n"
    "\n"
    "/* Ask the node to do something. Every button on this page ends up here: the\n"
    " * path becomes a call to a C function in mesh_network_v1.c (see\n"
    " * Website/site_actions.h). Nothing is expected back, so a failed request must\n"
    " * not break the page. */\n"
    "function askNode(url) {\n"
    "    fetch(url).catch(function () {});\n"
    "}\n"
    "\n"
    "async function loadMessages() {\n"
    "    const list = document.getElementById(\"emailList\");\n"
    "\n"
    "    /* Tell the node we refreshed, so it can reload its own letter store. */\n"
    "    askNode(\"/action/post_refresh\");\n"
    "\n"
    "    list.innerHTML =\n"
    "        '<div class=\"empty-inbox\">Fetching the letters...</div>';\n"
    "\n"
    "    try {\n"
    "        /* The Post Office reads its own private letters, not the public\n"
    "         * discussion of the hall. */\n"
    "        const response = await fetch(\"private_mesagges.txt\", {\n"
    "            cache: \"no-store\"\n"
    "        });\n"
    "\n"
    "        if (!response.ok) {\n"
    "            throw new Error(\"HTTP \" + response.status);\n"
    "        }\n"
    "\n"
    "        const text = await response.text();\n"
    "\n"
    "        messages = text.split(/\\r?\\n/)\n"
    "            .map((line, index) => {\n"
    "                const separator = line.indexOf(\":\");\n"
    "\n"
    "                if (separator === -1) return null;\n"
    "\n"
    "                const sender = line.slice(0, separator).trim();\n"
    "                const body = line.slice(separator + 1).trim();\n"
    "\n"
    "                if (!sender) return null;\n"
    "\n"
    "                return {\n"
    "                    sender: sender,\n"
    "                    body: body,\n"
    "                    id: index\n"
    "                };\n"
    "            })\n"
    "            .filter(message => message !== null);\n"
    "\n"
    "        selectedMessage = null;\n"
    "        renderInbox();\n"
    "\n"
    "        if (messages.length > 0) {\n"
    "            selectMessage(messages[0].id);\n"
    "        } else {\n"
    "            showEmptyViewer();\n"
    "        }\n"
    "\n"
    "    } catch (error) {\n"
    "        list.innerHTML = \"\";\n"
    "\n"
    "        const errorMessage = document.createElement(\"div\");\n"
    "        errorMessage.className = \"empty-inbox\";\n"
    "        errorMessage.textContent =\n"
    "            \"The letters could not be retrieved. \" +\n"
    "            \"Ensure private_mesagges.txt is beside this page. \" +\n"
    "            error.message;\n"
    "\n"
    "        list.appendChild(errorMessage);\n"
    "\n"
    "        document.getElementById(\"messageCount\").textContent = \"Error\";\n"
    "\n"
    "        showEmptyViewer();\n"
    "    }\n"
    "}\n"
    "\n"
    "function renderInbox() {\n"
    "    const list = document.getElementById(\"emailList\");\n"
    "\n"
    "    document.getElementById(\"messageCount\").textContent =\n"
    "        messages.length + \" letters\";\n"
    "\n"
    "    document.getElementById(\"listTitle\").textContent =\n"
    "        currentFolder === \"all\" ? \"All Messages\" : \"Inbox\";\n"
    "\n"
    "    document.getElementById(\"inboxFolder\")\n"
    "        .classList.toggle(\"active\", currentFolder === \"inbox\");\n"
    "\n"
    "    document.getElementById(\"allFolder\")\n"
    "        .classList.toggle(\"active\", currentFolder === \"all\");\n"
    "\n"
    "    if (messages.length === 0) {\n"
    "        list.innerHTML =\n"
    "            '<div class=\"empty-inbox\">No letters have arrived.</div>';\n"
    "        return;\n"
    "    }\n"
    "\n"
    "    list.innerHTML = \"\";\n"
    "\n"
    "    messages.forEach((message, index) => {\n"
    "        const row = document.createElement(\"button\");\n"
    "        row.type = \"button\";\n"
    "        row.className = \"email-row\";\n"
    "\n"
    "        if (selectedMessage && selectedMessage.id === message.id) {\n"
    "            row.classList.add(\"selected\");\n"
    "        }\n"
    "\n"
    "        const info = document.createElement(\"span\");\n"
    "        info.className = \"email-info\";\n"
    "\n"
    "        const sender = document.createElement(\"span\");\n"
    "        sender.className = \"email-sender\";\n"
    "        sender.textContent = message.sender;\n"
    "\n"
    "        const preview = document.createElement(\"span\");\n"
    "        preview.className = \"email-preview\";\n"
    "        preview.textContent = message.body || \"(Empty letter)\";\n"
    "\n"
    "        const number = document.createElement(\"span\");\n"
    "        number.className = \"email-number\";\n"
    "        number.textContent = \"#\" + (index + 1);\n"
    "\n"
    "        info.appendChild(sender);\n"
    "        info.appendChild(preview);\n"
    "\n"
    "        row.appendChild(info);\n"
    "        row.appendChild(number);\n"
    "\n"
    "        row.addEventListener(\"click\", () => selectMessage(message.id));\n"
    "\n"
    "        list.appendChild(row);\n"
    "    });\n"
    "}\n"
    "\n"
    "function selectMessage(id) {\n"
    "    const message = messages.find(item => item.id === id);\n"
    "    if (!message) return;\n"
    "\n"
    "    selectedMessage = message;\n"
    "    renderInbox();\n"
    "\n"
    "    const viewer = document.getElementById(\"messageViewer\");\n"
    "    viewer.innerHTML = \"\";\n"
    "\n"
    "    const heading = document.createElement(\"div\");\n"
    "    heading.className = \"viewer-header\";\n"
    "\n"
    "    const subject = document.createElement(\"h3\");\n"
    "    subject.className = \"viewer-subject\";\n"
    "    subject.textContent = \"A Letter from \" + message.sender;\n"
    "\n"
    "    const senderInfo = document.createElement(\"div\");\n"
    "    senderInfo.className = \"viewer-sender\";\n"
    "\n"
    "    const senderLabel = document.createElement(\"strong\");\n"
    "    senderLabel.textContent = message.sender;\n"
    "\n"
    "    senderInfo.appendChild(senderLabel);\n"
    "    heading.appendChild(subject);\n"
    "    heading.appendChild(senderInfo);\n"
    "\n"
    "    const body = document.createElement(\"div\");\n"
    "    body.className = \"viewer-body\";\n"
    "    body.textContent = message.body || \"(Empty letter)\";\n"
    "\n"
    "    viewer.appendChild(heading);\n"
    "    viewer.appendChild(body);\n"
    "}\n"
    "\n"
    "function showEmptyViewer() {\n"
    "    selectedMessage = null;\n"
    "\n"
    "    document.getElementById(\"messageViewer\").innerHTML = \"\";\n"
    "\n"
    "    const placeholder = document.createElement(\"div\");\n"
    "    placeholder.className = \"viewer-placeholder\";\n"
    "    placeholder.textContent = \"No letter selected.\";\n"
    "\n"
    "    document.getElementById(\"messageViewer\").appendChild(placeholder);\n"
    "}\n"
    "\n"
    "function showFolder(folder) {\n"
    "    askNode(\"/action/post_folder?folder=\" + encodeURIComponent(folder));\n"
    "\n"
    "    currentFolder = folder;\n"
    "    renderInbox();\n"
    "\n"
    "    if (messages.length > 0 && !selectedMessage) {\n"
    "        selectMessage(messages[0].id);\n"
    "    }\n"
    "}\n"
    "\n"
    "function openCompose() {\n"
    "    askNode(\"/action/compose_open\");\n"
    "\n"
    "    document.getElementById(\"composeWindow\")\n"
    "        .classList.remove(\"compose-collapsed\");\n"
    "\n"
    "    document.getElementById(\"recipient\").focus();\n"
    "}\n"
    "\n"
    "function toggleCompose() {\n"
    "    askNode(\"/action/compose_toggle\");\n"
    "\n"
    "    document.getElementById(\"composeWindow\")\n"
    "        .classList.toggle(\"compose-collapsed\");\n"
    "}\n"
    "\n"
    "document.getElementById(\"composeForm\").addEventListener(\n"
    "    \"submit\",\n"
    "    function(event) {\n"
    "        event.preventDefault();\n"
    "\n"
    "        const recipient = document.getElementById(\"recipient\").value.trim();\n"
    "        const textarea = document.getElementById(\"composeMessage\");\n"
    "        const letter = textarea.value.trim();\n"
    "\n"
    "        if (recipient === \"\" || letter === \"\") {\n"
    "            return;\n"
    "        }\n"
    "\n"
    "        /* The addressee goes in the query, the letter itself as the POST body:\n"
    "         * a letter may be far longer than a URL. site_action_post_send() gets\n"
    "         * both. */\n"
    "        fetch(\"/action/post_send?recipient=\" + encodeURIComponent(recipient), {\n"
    "            method: \"POST\",\n"
    "            body: letter\n"
    "        }).catch(function () {});\n"
    "\n"
    "        document.querySelector(\".compose-hint\").textContent =\n"
    "            \"Dispatched to the node\";\n"
    "    }\n"
    ");\n"
    "\n"
    "loadMessages();\n"
    "</script>\n"
    "\n"
    "</body>\n"
    "</html>\n"
    ;

