static const char site_kings_court_html_name[] = "Website/Kings_Court/Kings_Court.html";

/* The URL the browser types -> the bytes to hand back. Both "/" and "/index.html"
 * are the home page, because the sidebar links use the absolute form and the
 * browser's own address bar may use either. */
static const site_asset_t site_asset_table[] = {
    { "/", site_index_html_name, site_index_html_body, sizeof(site_index_html_body) - 1u, "text/html; charset=utf-8" },
    { "/index.html", site_index_html_name, site_index_html_body, sizeof(site_index_html_body) - 1u, "text/html; charset=utf-8" },
    { "/Discussion_Hall/Discussion_Hall.html", site_discussion_hall_html_name, site_discussion_hall_html_body, sizeof(site_discussion_hall_html_body) - 1u, "text/html; charset=utf-8" },
    { "/Discussion_Hall/current_discussion.txt", site_current_discussion_txt_name, site_current_discussion_txt_body, sizeof(site_current_discussion_txt_body) - 1u, "text/plain; charset=utf-8" },
    { "/Post_Office/Post_Office.html", site_post_office_html_name, site_post_office_html_body, sizeof(site_post_office_html_body) - 1u, "text/html; charset=utf-8" },
    { "/Post_Office/private_mesagges.txt", site_private_mesagges_txt_name, site_private_mesagges_txt_body, sizeof(site_private_mesagges_txt_body) - 1u, "text/plain; charset=utf-8" },
    { "/Kings_Court/Kings_Court.html", site_kings_court_html_name, site_kings_court_html_body, sizeof(site_kings_court_html_body) - 1u, "text/html; charset=utf-8" },
};

#define SITE_ASSET_COUNT (sizeof(site_asset_table) / sizeof(site_asset_t))

/* Linear scan over seven entries: cheaper to read than a hash, and the table is
 * tiny and fixed at compile time. */
const site_asset_t *site_find_asset(const char *path)
{
    for (size_t i = 0; i < SITE_ASSET_COUNT; ++i)
    {
        if (strcmp(site_asset_table[i].path, path) == 0)
            return &site_asset_table[i];
    }

    return NULL;
}
